#!/usr/bin/env bash

# Managed by componentized/build and synced into each repository by `make update-build`. Change it
# in https://github.com/componentized/build, `make check-build` fails when a copy is changed.

# Generate the CycloneDX SBOM of a component the build makes, or of the interface, from how it's made.
#
#   build/scripts/sbom.sh cargo <wasm> <out> <package sbom> <target>  a component built with cargo
#   build/scripts/sbom.sh composition <wasm> <out> <sbom>...     composed or plugged with wac
#   build/scripts/sbom.sh generated <wasm> <out> <crate> <version>  generated by a cli, e.g. constants
#   build/scripts/sbom.sh oci <wasm> <out> <image>               pulled with wkg, e.g. a dep- component
#   build/scripts/sbom.sh interface <wasm> <out> <wkg.lock>      the interface, built with wkg
#
# The SBOM describes the wasm file as its component, `metadata.component`, by its SHA-256, the digest
# of the layer it's published as, and lists what it's made from:
#
#   cargo        the package and the crates it depends on built for its target, from the SBOM
#                build/scripts/sbom-cargo.sh generated for the package, the Rust standard library of
#                the toolchain, by the commit of rustc, and the wasi-libc it links for a wasm32-wasi*
#                target: for wasm32-wasip3 the wasi-libc of the wasi-sdk sysroot, or the one built from
#                WASI_LIBC_VERSION, otherwise the wasi-libc bundled with the standard library. Each
#                adapter the component embeds, e.g. wasi_snapshot_preview1 embedded by
#                wasm-component-ld or `wasm-tools component new --adapt`, by its SHA-256
#   composition  the components it's composed from, each with what it's made from, from their SBOMs
#   generated    the crate of the cli it's generated with, e.g. componentized-constants-cli, whose
#                code it embeds
#   oci          what the SBOM attested to the image it's pulled from says, verified with cosign, or
#                else nothing, it is the image, named by its purl and OCI coordinates
#   interface    the WIT packages it depends on, from wkg.lock
#
# The component is named by the directory's id of the package it's published as, e.g.
# componentized:build-greeter for greeter.wasm and greeter.debug.wasm of componentized/build,
# componentized:build for the interface, as build/scripts/publish.sh names it, and referenced as
# `component:<id>`, e.g. component:componentized:build-greeter. A component pulled
# with wkg is named after the image it's pulled from, e.g. componentized:logging-to-stderr for
# ghcr.io/componentized/logging/to-stderr. Its version and image are known when it's published,
# build/scripts/publish.sh adds them.
#
# GITHUB_REPOSITORY       the GitHub repository the components are built from, e.g. componentized/http,
#                         defaults to the componentized repository named after the checkout
# COSIGN                  the cosign binary, to verify the SBOM attested to an image a component is
#                         pulled from, defaults to cosign on the PATH, without it the SBOM is made from
#                         the image alone
# SOURCE_DATE_EPOCH       the time the SBOM is generated at, e.g. the time of the commit, for an SBOM
#                         that is the same each time it is generated, defaults to now
# WASM_TOOLS              the wasm-tools binary, to find the adapters a component embeds, defaults to
#                         wasm-tools on the PATH
# WASI_SDK_PATH           the wasi-sdk a wasm32-wasip3 component is linked with, see build/tools.mk
# WASI_LIBC_VERSION       the wasi-libc a wasm32-wasip3 component links when built from source, a
#                         commit or tag, empty for the wasi-sdk sysroot's
# WASI_LIBC_WASI_VERSION  the WASI 0.3 version the wasi-libc built from WASI_LIBC_VERSION was rewritten
#                         to import

set -euo pipefail

cd "$(dirname "$0")/../.."

kind="${1:-}"
wasm="${2:-}"
out="${3:-}"
if [[ -z "$kind" || -z "$wasm" || -z "$out" ]]; then
    echo "usage: $0 <cargo|composition|generated|oci|interface> <wasm> <out> ..., e.g. cargo target/components/greeter/greeter.wasm target/components/greeter/greeter.cdx.json target/sbom/cargo/wasm32-wasip2/greeter.cdx.json" >&2
    exit 1
fi
shift 3

component=$(basename "$wasm" .wasm)
component="${component%.debug}"
# the directory's id of the package, as build/scripts/publish.sh names it
GITHUB_REPOSITORY="${GITHUB_REPOSITORY:-componentized/$(basename "$(git rev-parse --show-toplevel)")}"
if [[ "$kind" == interface ]]; then
    name="${GITHUB_REPOSITORY/\//:}"
else
    name="${GITHUB_REPOSITORY/\//:}-${component}"
fi
sha256=$( (sha256sum "$wasm" 2> /dev/null || shasum -a 256 "$wasm") | cut -d' ' -f1)
epoch="${SOURCE_DATE_EPOCH:-$(date +%s)}"

# the SBOM of the component, made of what's given as $components, $dependencies, what the component
# depends on directly as $depends_on, and the tools it's generated with as $tools
bom='
    {type: "library", "bom-ref": "component:\($name)", name: $name, hashes: [{alg: "SHA-256", content: $sha256}]} as $component
    | {
        bomFormat: "CycloneDX",
        specVersion: "1.6",
        version: 1,
        metadata: {
          timestamp: ($epoch | tonumber | todate),
          tools: {components: $tools},
          component: ($component + $root)
        },
        components: $components,
        dependencies: ([{ref: $component["bom-ref"], dependsOn: $depends_on}] + $dependencies)
      }
'

case "$kind" in
    cargo)
        package_sbom="${1:?the SBOM of the package is undefined}"
        target="${2:?the target the component is built for is undefined}"
        # the component's package, the SBOM is named for it, e.g. greeter.cdx.json, which may differ
        # from the component's name, e.g. hello for example-hello
        package=$(basename "$package_sbom" .cdx.json)

        # the Rust standard library, of the toolchain the repository pins, by the commit of rustc
        rustc=$(rustc -vV)
        rust_release=$(sed -n 's/^release: //p' <<< "$rustc")
        rust_commit=$(sed -n 's/^commit-hash: //p' <<< "$rustc")

        # the wasi-libc a wasm32-wasip3 component links, and the wasi-sdk it's linked with, as JSON
        wasi_libc=null
        wasi_sdk=null
        if [[ "$target" == wasm32-wasip3 ]]; then
            : "${WASI_SDK_PATH:?WASI_SDK_PATH is undefined, the wasi-sdk a wasm32-wasip3 component is linked with}"
            # e.g. `34.0` followed by `wasi-libc: 2e6fb9d8ee0c`
            sdk_version=$(head -1 "${WASI_SDK_PATH}/VERSION")
            wasi_sdk=$(jq -n --arg version "$sdk_version" '{type: "application", name: "wasi-sdk", version: $version}')
            if [[ -n "${WASI_LIBC_VERSION:-}" ]]; then
                wasi_libc=$(jq -n --arg version "$WASI_LIBC_VERSION" --arg wasi "${WASI_LIBC_WASI_VERSION:-}" --arg sdk "$sdk_version" '{
                    version: $version,
                    description: "built from source with wasi-sdk \($sdk)",
                    pedigree: (if $wasi != "" then {notes: "its WASI 0.3 bindings rewritten to import WASI \($wasi)"} else null end)
                } | del(..|nulls)')
            else
                wasi_libc=$(jq -n --arg version "$(sed -n 's/^wasi-libc: //p' "${WASI_SDK_PATH}/VERSION")" --arg sdk "$sdk_version" '{
                    version: $version,
                    description: "the experimental-coop-threads sysroot of wasi-sdk \($sdk)"
                }')
            fi
        elif [[ "$target" == wasm32-wasi* ]]; then
            wasi_libc=$(jq -n --arg target "$target" --arg release "$rust_release" '{
                description: "bundled with the Rust standard library for \($target) of rustc \($release)"
            }')
        fi

        # each adapter the component embeds, a module wit-component names `wit-component:adapter:<name>`,
        # by the SHA-256 of its bytes
        adapters=$(
            "${WASM_TOOLS:-wasm-tools}" metadata show --json "$wasm" \
                | jq -c '.. | objects | select(has("module")) | .module | select((.name // "") | startswith("wit-component:adapter:"))' \
                | while read -r module; do
                    start=$(jq -r '.range.start' <<< "$module")
                    end=$(jq -r '.range.end' <<< "$module")
                    adapter_sha256=$(tail -c +$((start + 1)) "$wasm" | head -c $((end - start)) | (sha256sum 2> /dev/null || shasum -a 256) | cut -d' ' -f1)
                    jq -c --arg sha256 "$adapter_sha256" '{name: (.name | ltrimstr("wit-component:adapter:")), sha256: $sha256, producers: (.producers // [])}' <<< "$module"
                done \
                | jq -s '.'
        )

        # the crates whose code the component can contain, e.g. ["greeter@0.1.0", "wit-bindgen@0.63.0"]:
        # the package and its normal dependencies for the target, without the proc-macros and the
        # crates only they depend on, e.g. syn and wit-parser, which run as it's compiled
        runtime=$(
            cargo tree --quiet --locked -p "$package" --target "$target" -e normal,no-proc-macro --prefix none --format '{p}' \
                | sed -E 's/ \(.*//; s/ v/@/' \
                | sort -u \
                | jq -R . | jq -s .
        )

        # cargo-cyclonedx names the package by its path, absolute, it's made relative to the
        # repository, e.g. path+file://./components/greeter#0.1.0. The package's targets are dropped,
        # the component is built from one of them. A crate the component's code can't contain is
        # scoped `excluded`, it's listed, with its version, hashes and licenses, as a crate the
        # component is built with rather than one it's made of.
        jq --arg name "$name" --arg sha256 "$sha256" --arg epoch "$epoch" --arg root "$PWD" \
            --arg target "$target" --arg rust_release "$rust_release" --arg rust_commit "$rust_commit" \
            --argjson wasi_libc "$wasi_libc" --argjson wasi_sdk "$wasi_sdk" --argjson adapters "$adapters" \
            --argjson runtime "$runtime" '
            walk(if type == "string" then gsub($root; ".") else . end)
            | .components |= map(if "\(.name)@\(.version)" | IN($runtime[]) then . else . + {scope: "excluded"} end)
            | (.metadata.component | del(.components)) as $package
            | "pkg:github/rust-lang/rust@\($rust_commit)" as $rust_purl
            | {
                type: "library",
                "bom-ref": "rust-std:\($rust_commit):\($target)",
                name: "rust-std",
                version: $rust_release,
                description: "the Rust standard library for \($target)",
                purl: $rust_purl
              } as $rust_std
            | (if $wasi_libc == null then null
               elif $wasi_libc.version then
                 {type: "library", "bom-ref": "pkg:github/webassembly/wasi-libc@\($wasi_libc.version)", name: "wasi-libc", purl: "pkg:github/webassembly/wasi-libc@\($wasi_libc.version)"} + $wasi_libc
               else
                 {type: "library", "bom-ref": "wasi-libc:\($rust_commit):\($target)", name: "wasi-libc"} + $wasi_libc
               end) as $libc
            | [$adapters[] | {
                type: "library",
                "bom-ref": "adapter:\(.name)@\(.sha256)",
                name: .name,
                description: "a WASI adapter embedded in the component",
                hashes: [{alg: "SHA-256", content: .sha256}],
                properties: [.producers[] | .[0] as $field | .[1] | to_entries[] | {name: "producers:\($field):\(.key)", value: .value}]
              }] as $adapter_components
            | ([.metadata.tools[]? | {type: "application", name, version}] + [$wasi_sdk | values]) as $tools
            | {} as $root
            | ([$package, $rust_std, ($libc | values)] + $adapter_components + (.components // [])) as $components
            | ((.dependencies // [])
               + [{ref: $rust_std["bom-ref"], dependsOn: [$libc | values | .["bom-ref"]]}]
               + [$libc | values | {ref: .["bom-ref"], dependsOn: []}]
               + [$adapter_components[] | {ref: .["bom-ref"], dependsOn: []}]) as $dependencies
            | ([$package["bom-ref"], $rust_std["bom-ref"], ($libc | values | .["bom-ref"])] + [$adapter_components[]["bom-ref"]]) as $depends_on
            | '"$bom" "$package_sbom" > "$out"
        ;;
    composition)
        if [[ $# -eq 0 ]]; then
            echo "the SBOMs of the components composed are undefined" >&2
            exit 1
        fi
        # each component composed, with what it's made from, a crate two components depend on is
        # listed once
        jq -n --arg name "$name" --arg sha256 "$sha256" --arg epoch "$epoch" '
            [inputs] as $sboms
            | ([$sboms[].metadata.tools.components[]?] | unique_by([.name, .version])) as $tools
            | {} as $root
            # a crate one component is made of and another only built with, scoped `excluded`, is
            # one the composition is made of
            | ([$sboms[] | [.metadata.component] + .components] | add | group_by(.["bom-ref"])
               | map(if any(.[]; .scope != "excluded") then (map(select(.scope != "excluded")) | .[0]) else .[0] end)) as $components
            | ([$sboms[].dependencies[]] | unique_by(.ref)) as $dependencies
            | [$sboms[].metadata.component["bom-ref"]] as $depends_on
            | '"$bom" "$@" > "$out"
        ;;
    generated)
        crate="${1:?the crate of the cli is undefined}"
        version="${2:?the version of the cli is undefined}"
        jq -n --arg name "$name" --arg sha256 "$sha256" --arg epoch "$epoch" --arg crate "$crate" --arg version "$version" '
            "pkg:cargo/\($crate)@\($version)" as $purl
            | [{type: "application", name: $crate, version: $version}] as $tools
            | {} as $root
            | [{type: "library", "bom-ref": $purl, name: $crate, version: $version, purl: $purl}] as $components
            | [{ref: $purl, dependsOn: []}] as $dependencies
            | [$purl] as $depends_on
            | '"$bom" > "$out"
        ;;
    oci)
        image="${1:?the image is undefined}"
        # e.g. ghcr.io/componentized/logging/to-stderr:0.3.1@sha256:... is
        # pkg:oci/to-stderr@sha256%3A...?repository_url=ghcr.io/componentized/logging/to-stderr&tag=0.3.1
        repository="${image%%@*}"
        digest=""
        [[ "$image" == *@* ]] && digest="${image#*@}"
        tag=""
        if [[ "${repository##*/}" == *:* ]]; then
            tag="${repository##*:}"
            repository="${repository%:*}"
        fi
        # the directory's id of the image's package, e.g. componentized:logging-to-stderr for
        # ghcr.io/componentized/logging/to-stderr, the registry dropped, then the namespace and the
        # rest of the path joined with `-`
        path="${repository#*/}"
        rest="${path#*/}"
        name="${path%%/*}:${rest//\//-}"
        # the SBOM published with the image, attested with cosign as build/scripts/publish.sh attests
        # it, verified to be signed by a GitHub Actions workflow of the image's org, e.g.
        # https://github.com/componentized/... for ghcr.io/componentized/logging/to-stderr. Without
        # cosign, a digest, or a verified attestation, e.g. an image published before its SBOM was,
        # the SBOM is made from the image alone.
        published=null
        cosign="${COSIGN:-cosign}"
        org="${path%%/*}"
        if [[ -z "$digest" ]]; then
            echo "not fetching the SBOM of ${image}, it has no digest" >&2
        elif ! command -v "$cosign" > /dev/null; then
            echo "not fetching the SBOM attested to ${repository}@${digest}, cosign is not installed" >&2
        elif envelopes=$("$cosign" verify-attestation --type cyclonedx \
                --certificate-identity-regexp "^https://github\.com/${org}/" \
                --certificate-oidc-issuer https://token.actions.githubusercontent.com \
                "${repository}@${digest}" 2> /dev/null) && [[ -n "$envelopes" ]]; then
            # each attestation verified is a DSSE envelope of an in-toto statement whose predicate is
            # the SBOM, the last is used
            published=$(tail -1 <<< "$envelopes" | jq '.payload | @base64d | fromjson | .predicate')
            published_sha256=$(jq -r '.metadata.component.hashes[]? | select(.alg == "SHA-256") | .content' <<< "$published")
            if [[ -n "$published_sha256" && "$published_sha256" != "$sha256" ]]; then
                echo "the SBOM attested to ${repository}@${digest} describes a component with the SHA-256 ${published_sha256}, not ${wasm}'s ${sha256}" >&2
                exit 1
            fi
            echo "using the SBOM attested to ${repository}@${digest}" >&2
        else
            echo "no SBOM attested to ${repository}@${digest} by a workflow of github.com/${org} verified, the SBOM is made from the image alone" >&2
        fi

        # the image's OCI coordinates: the registry, the repository in it, the tag and the digest, e.g.
        # ghcr.io, componentized/logging/to-stderr, 0.3.1 and sha256:..., and the reference it's
        # pulled by. The version is the tag's, a debug build's `_debug` tag is version `+debug`, as
        # build/scripts/publish.sh tags it, e.g. 0.3.1_debug is 0.3.1+debug. A published SBOM is the
        # base: what it says of the component, its version, licenses and what it's made from, is kept,
        # and the component's SHA-256, OCI coordinates and the reference to the SBOM are added.
        jq -n --arg name "$name" --arg sha256 "$sha256" --arg epoch "$epoch" --arg image "$image" --arg repository "$repository" --arg digest "$digest" --arg tag "$tag" --argjson published "$published" '
            ($repository | split("/") | last) as $last
            | "pkg:oci/\($last)\(if $digest != "" then "@\($digest | sub(":"; "%3A"))" else "" end)?repository_url=\($repository)\(if $tag != "" then "&tag=\($tag)" else "" end)" as $purl
            | [{type: "application", name: "wkg"}] as $tools
            | {
                version: (if $tag != "" then $tag | sub("_"; "+") else null end),
                purl: $purl,
                externalReferences: [{type: "distribution", url: "oci://\($image)", comment: "the OCI image the component is pulled from with wkg"}],
                properties: [
                  {name: "oci:registry", value: ($repository | split("/") | first)},
                  {name: "oci:repository", value: ($repository | split("/") | .[1:] | join("/"))},
                  (if $tag != "" then {name: "oci:tag", value: $tag} else empty end),
                  (if $digest != "" then {name: "oci:digest", value: $digest} else empty end)
                ]
              } | del(..|nulls) as $root
            | [] as $components
            | [] as $dependencies
            | [] as $depends_on
            | '"$bom"'
            | if $published == null then . else
                . as $local
                | $published
                | .metadata.timestamp = $local.metadata.timestamp
                | .metadata.tools = {components: ([(.metadata.tools | if type == "array" then .[] else .components[]? end)] + $local.metadata.tools.components + [{type: "application", name: "cosign"}] | unique_by(.name))}
                | .metadata.component |= (
                    .hashes = $local.metadata.component.hashes
                    | .purl = $local.metadata.component.purl
                    | .version //= $local.metadata.component.version
                    | .externalReferences = ((.externalReferences // []) + $local.metadata.component.externalReferences + [{
                        type: "bom",
                        url: "oci://\($repository)@\($digest)",
                        comment: "the SBOM attested to the image with cosign, the base of this SBOM"
                      }])
                    | .properties = ((.properties // []) + $local.metadata.component.properties)
                  )
              end
        ' > "$out"
        ;;
    interface)
        lock="${1:?the wkg.lock is undefined}"
        # each version of each package in wkg.lock, a line of its name, registry, version and digest. A
        # missing lock has no packages, e.g. an interface without dependencies.
        packages=""
        [[ -f "$lock" ]] && packages=$(awk '
            /^\[\[packages\]\]/ { name = ""; registry = "" }
            /^name = / { gsub(/"/, "", $3); name = $3 }
            /^registry = / { gsub(/"/, "", $3); registry = $3 }
            /^version = / && name != "" { gsub(/"/, "", $3); version = $3 }
            /^digest = / && name != "" { gsub(/"/, "", $3); print name "\t" registry "\t" version "\t" $3 }
        ' "$lock")
        jq -n -R --arg name "$name" --arg sha256 "$sha256" --arg epoch "$epoch" '
            [inputs | select(. != "") | split("\t") | {name: .[0], registry: .[1], version: .[2], digest: .[3]}] as $packages
            | [{type: "application", name: "wkg"}] as $tools
            | {} as $root
            | [$packages[] | {
                type: "library",
                "bom-ref": "wit:\(.name)@\(.version)",
                name,
                version,
                hashes: [{alg: "SHA-256", content: (.digest | ltrimstr("sha256:"))}],
                properties: [{name: "wkg:registry", value: .registry}]
              }] as $components
            | [$components[] | {ref: .["bom-ref"], dependsOn: []}] as $dependencies
            | [$components[]["bom-ref"]] as $depends_on
            | '"$bom" <<< "$packages" > "$out"
        ;;
    *)
        echo "unknown kind ${kind}, one of cargo, composition, generated, oci or interface" >&2
        exit 1
        ;;
esac
